package kr.blackwiki.smp;

import com.google.gson.*;
import org.bukkit.configuration.file.YamlConfiguration;
import org.junit.jupiter.api.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import static org.junit.jupiter.api.Assertions.*;

class Discord29Test {
    static final String G="111111111111111111",C="222222222222222222",U="333333333333333333",R="444444444444444444";
    static JsonObject event(String id,String content){return JsonParser.parseString("{\"id\":\""+id+"\",\"guild_id\":\""+G+"\",\"channel_id\":\""+C+"\",\"author\":{\"id\":\""+U+"\",\"username\":\"홍길동\",\"bot\":false},\"member\":{\"roles\":[\""+R+"\"]},\"content\":"+new Gson().toJson(content)+"}").getAsJsonObject();}
    static DiscordInbound.Message message(String user,Set<String> roles,String text){return new DiscordInbound.Message("999999999999999999",G,C,user,"User",roles,text);}
    static PowerCommands.Policy policy(){return new PowerCommands.Policy(true,G,C,Set.of(U),Set.of(R),30);}
    static final class Actions implements PowerCommands.Actions{int starts,stops;public String start(){starts++;return "start";}public String stop(){stops++;return "stop";}public String status(){return "status";}}
    @Test void incomingKoreanAndRolesSurviveWithoutLosingLargeIds(){var m=new DiscordInbound().parse(event("999999999999999999","안녕하세요 😀"),"");assertEquals(U,m.author());assertEquals("안녕하세요 😀",m.content());assertTrue(m.roles().contains(R));assertEquals("홍길동",m.name());}
    @Test void resumedMessageIsDeliveredOnlyOnce(){var p=new DiscordInbound();var e=event("999999999999999999","hello");assertNotNull(p.parse(e,""));assertNull(p.parse(e,""));}
    @Test void botsWebhooksSelfSystemAndDmAreExcluded(){for(String mode:List.of("bot","system","webhook","dm","self")){var e=event("999999999999999999","test");switch(mode){case "bot","system"->e.getAsJsonObject("author").addProperty(mode,true);case "webhook"->e.addProperty("webhook_id","555555555555555555");case "dm"->e.remove("guild_id");}assertNull(new DiscordInbound().parse(e,mode.equals("self")?U:""),mode);}}
    @Test void malformedOrOversizedEventsDoNotEscapeParser(){for(JsonObject e:List.of(new JsonObject(),event("abc","x"),event("999999999999999999","x".repeat(4001)),event("999999999999999999","  "))){assertNull(new DiscordInbound().parse(e,""));}var e=event("999999999999999999","x");e.addProperty("type",7);assertNull(new DiscordInbound().parse(e,""));}
    @Test void nameAndTextAreLiteralWithoutControlCharacters(){assertEquals("name  x",DiscordInbound.plain("name\u0000\u200bx",48));assertEquals("/op Steve",new DiscordInbound().parse(event("999999999999999999","/op Steve"),"").content());}
    @Test void chatRoutingChecksConfiguredGuildAndChannel(){YamlConfiguration y=new YamlConfiguration();y.set("discord.guild-id",G);y.set("discord.channel-id",C);var o=DiscordOptions.read(y);assertTrue(DiscordInbound.chatChannel(message(U,Set.of(),"x"),o));assertFalse(DiscordInbound.chatChannel(new DiscordInbound.Message("9","000000000000000000",C,U,"x",Set.of(),"x"),o));}
    @Test void explicitUserOrRoleIsRequiredInExactGuildAndChannel(){var p=policy();assertTrue(p.allowed(message(U,Set.of(),"x")));assertTrue(p.allowed(message("555555555555555555",Set.of(R),"x")));assertFalse(p.allowed(message("555555555555555555",Set.of(),"x")));assertFalse(p.allowed(new DiscordInbound.Message("9","000000000000000000",C,U,"x",Set.of(R),"x")));assertFalse(p.allowed(new DiscordInbound.Message("9",G,"000000000000000000",U,"x",Set.of(R),"x")));}
    @Test void emptyAllowlistAndDisabledPolicyDenyEveryone(){assertFalse(new PowerCommands.Policy(true,G,C,Set.of(),Set.of(),30).allowed(message(U,Set.of(),"!서버켜기")));assertFalse(new PowerCommands.Policy(false,G,C,Set.of(U),Set.of(),30).allowed(message(U,Set.of(),"!서버켜기")));}
    @Test void unauthorizedUsersCannotStartOrStop(){var p=new PowerCommands(policy());var a=new Actions();p.handle(message("555555555555555555",Set.of(),"!서버켜기"),0,a);p.handle(message("555555555555555555",Set.of(),"!서버끄기"),0,a);assertEquals(0,a.starts+a.stops);}
    @Test void startIsFixedAndExtraArgumentsCannotRunShell(){var p=new PowerCommands(policy());var a=new Actions();assertEquals("start",p.handle(message(U,Set.of(),"!서버켜기"),0,a));p.handle(message(U,Set.of(),"!서버켜기 ; touch injected"),0,a);assertNull(p.handle(message(U,Set.of(),"/op Steve"),0,a));assertEquals(1,a.starts);}
    String nonce(PowerCommands p,Actions a,long now){String result=p.handle(message(U,Set.of(),"!서버끄기"),now,a);return result.split("확인 ")[1].split("`")[0];}
    @Test void stopRequiresSingleUseConfirmationFromSameUser(){var p=new PowerCommands(policy());var a=new Actions();String n=nonce(p,a,1000);assertEquals(0,a.stops);p.handle(message("555555555555555555",Set.of(R),"!서버끄기 확인 "+n),2000,a);assertEquals(0,a.stops);assertEquals("stop",p.handle(message(U,Set.of(),"!서버끄기 확인 "+n),2000,a));p.handle(message(U,Set.of(),"!서버끄기 확인 "+n),2001,a);assertEquals(1,a.stops);}
    @Test void expiredOrWrongConfirmationNeverStops(){var p=new PowerCommands(policy());var a=new Actions();String n=nonce(p,a,0);p.handle(message(U,Set.of(),"!서버끄기 확인 wrong"),1,a);p.handle(message(U,Set.of(),"!서버끄기 확인 "+n),30000,a);assertEquals(0,a.stops);}
    @Test void confirmationRechecksCurrentRoleMembership(){var onlyRole=new PowerCommands(new PowerCommands.Policy(true,G,C,Set.of(),Set.of(R),30));var a=new Actions();String text=onlyRole.handle(message(U,Set.of(R),"!서버끄기"),0,a),n=text.split("확인 ")[1].split("`")[0];onlyRole.handle(message(U,Set.of(),"!서버끄기 확인 "+n),1000,a);assertEquals(0,a.stops);}
    @Test void tokenCannotAppearInSettingsOrOptionsToString(){var y=new YamlConfiguration();y.set("discord.bot-token","unit-test-token-123456789");var o=DiscordOptions.read(y);assertFalse(o.toString().contains(o.token()));assertFalse(o.outgoing().toString().contains(o.token()));}
    @Test void priorityKeepsJoinBeforeQuitAndEvictsNormalOverflow(){List<String> sent=new ArrayList<>();try(var q=new DiscordRelay(ModerationTest.settings(2),(u,t,b)->{sent.add(b);return new DiscordRelay.Reply(200,"{}",Map.of());},false)){q.offer("normal1");q.offer("normal2");assertTrue(q.priority("join"));assertTrue(q.priority("quit"));q.pump(0);String content=JsonParser.parseString(sent.getFirst()).getAsJsonObject().get("content").getAsString();assertEquals("join\nquit",content);assertEquals(2,q.dropped.get());}}
    @Test void unchangedReloadPreservesPendingLifecycleMessages(){try(var q=new DiscordRelay(ModerationTest.settings(10),(u,t,b)->new DiscordRelay.Reply(200,"{}",Map.of()),false)){q.priority("join");q.reload(ModerationTest.settings(10));assertEquals(1,q.queued());q.pump(0);assertEquals(1,q.sent.get());}}
    @Test void permanentHttpFailureClearsUrgentMessagesAndCanBeRetriedAfterReload(){AtomicInteger calls=new AtomicInteger();try(var q=new DiscordRelay(ModerationTest.settings(10),(u,t,b)->new DiscordRelay.Reply(calls.incrementAndGet()==1?401:200,"{}",Map.of()),false)){q.priority("first");q.pump(0);assertEquals(0,q.queued());q.reload(ModerationTest.settings(10));assertTrue(q.priority("retry"));q.pump(0);assertEquals(1,q.sent.get());}}
    @Test void concurrentPumpsCannotSendSameBatchTwice()throws Exception{var entered=new CountDownLatch(1);var release=new CountDownLatch(1);AtomicInteger count=new AtomicInteger();try(var q=new DiscordRelay(ModerationTest.settings(10),(u,t,b)->{count.incrementAndGet();entered.countDown();release.await();return new DiscordRelay.Reply(200,"{}",Map.of());},false)){q.offer("x");Thread first=Thread.startVirtualThread(()->q.pump(0));assertTrue(entered.await(2,TimeUnit.SECONDS));q.pump(0);release.countDown();first.join(2000);assertEquals(1,count.get());}}
    @Test void gracefulCloseFlushesShutdownBeforeClosingTransport(){List<String> sent=new CopyOnWriteArrayList<>();try(var q=new DiscordRelay(ModerationTest.settings(10),(u,t,b)->{sent.add(b);return new DiscordRelay.Reply(200,"{}",Map.of());},true)){q.priority("server stopped");q.closeGracefully(1500);assertEquals(1,sent.size());assertFalse(q.offer("after close"));}}
}
